1	// MIA 2.0 Glass-Box — botão "Modo IA" (sidebar + mobile header)
2	//
3	// Toggle persistente que ativa/desativa o split-view glass-box.
4	// Coexiste com FAB + página /mia (não substitui).
5	//
6	// Doc: docs/mia/ARCHITECTURE.md (Section 9.2), docs/mia/IMPLEMENTATION.md (2.2)
7	
8	import { Sparkles } from 'lucide-react';
9	import { useMiaGlassBoxContext } from '@/shared/contexts/MiaContext';
10	import { usePermissions } from '@/shared/hooks/usePermissions';
11	import { Button } from '@/shared/ui/button';
12	import { Badge } from '@/shared/ui/badge';
13	import { cn } from '@/shared/lib/utils';
14	
15	interface MiaModeToggleProps {
16	  variant?: 'sidebar' | 'compact';
17	  className?: string;
18	}
19	
20	/**
21	 * Botão "Modo IA" — ativa o glass-box pane (split view com MIA operando).
22	 *
23	 * Variants:
24	 * - sidebar: full-width na sidebar desktop (com label "Modo IA" + Badge ON)
25	 * - compact: ícone-only no header mobile (ao lado do StoreSelector)
26	 */
27	export function MiaModeToggle({ variant = 'sidebar', className }: MiaModeToggleProps) {
28	  const { miaModeEnabled, toggleMiaMode } = useMiaGlassBoxContext();
29	  const { canViewMia } = usePermissions();
30	
31	  if (!canViewMia()) return null;
32	
33	  if (variant === 'compact') {
34	    return (
35	      <Button
36	        type="button"
37	        variant={miaModeEnabled ? 'default' : 'outline'}
38	        size="icon"
39	        onClick={toggleMiaMode}
40	        aria-label={miaModeEnabled ? 'Desativar Modo IA' : 'Ativar Modo IA'}
41	        aria-pressed={miaModeEnabled}
42	        title={miaModeEnabled ? 'Modo IA ON' : 'Modo IA OFF'}
43	        data-mia-action="toggle-mia-mode"
44	        className={cn(
45	          'h-9 w-9 shrink-0 transition-all',
46	          miaModeEnabled && 'bg-gradient-to-br from-emerald-500 to-teal-600 text-white hover:from-emerald-600 hover:to-teal-700 border-transparent',
47	          className,
48	        )}
49	      >
50	        <Sparkles className={cn('h-4 w-4', miaModeEnabled && 'animate-pulse')} />
51	      </Button>
52	    );
53	  }
54	
55	  // variant === 'sidebar'
56	  return (
57	    <Button
58	      type="button"
59	      variant="ghost"
60	      onClick={toggleMiaMode}
61	      aria-pressed={miaModeEnabled}
62	      data-mia-action="toggle-mia-mode"
63	      className={cn(
64	        'w-full justify-start gap-2 h-9 px-2',
65	        miaModeEnabled && 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 hover:bg-emerald-500/15',
66	        className,
67	      )}
68	    >
69	      <Sparkles className={cn('h-4 w-4', miaModeEnabled && 'animate-pulse')} />
70	      <span className="text-sm">Modo IA</span>
71	      {miaModeEnabled ? (
72	        <Badge variant="secondary" className="ml-auto text-[10px] px-1.5 py-0">
73	          ON
74	        </Badge>
75	      ) : (
76	        <span className="ml-auto text-[10px] text-muted-foreground">desligado</span>
77	      )}
78	    </Button>
79	  );
80	}
