1	import { useState } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { SquarePen, History, ChevronLeft } from 'lucide-react';
4	import { Button } from '@/shared/ui/button';
5	import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
6	import { useMia } from '@/shared/contexts/MiaContext';
7	import { MiaHistoryPopoverContent } from './MiaHistoryPopover';
8	
9	interface MiaChatHeaderProps {
10	  conversationTitle?: string;
11	  onNewConversation: () => void;
12	}
13	
14	export function MiaChatHeader({
15	  conversationTitle,
16	  onNewConversation,
17	}: MiaChatHeaderProps) {
18	  const {
19	    conversations,
20	    activeConversationId,
21	    switchConversation,
22	    deleteConversation,
23	  } = useMia();
24	  const [popoverOpen, setPopoverOpen] = useState(false);
25	  const navigate = useNavigate();
26	
27	  return (
28	    <header className="h-[60px] flex items-center justify-between px-3 lg:px-5 sticky top-0 z-20 shrink-0 border-b border-[--mia-glass-border]/40">
29	      <div className="flex items-center gap-2 overflow-hidden min-w-0">
30	        <Button
31	          variant="ghost"
32	          size="icon"
33	          onClick={() => navigate('/dashboard')}
34	          className="h-10 w-10 text-[--mia-text-secondary] hover:text-[--mia-text-primary] md:hidden shrink-0 -ml-1"
35	          title="Voltar ao painel"
36	        >
37	          <ChevronLeft className="h-6 w-6" />
38	        </Button>
39	
40	        <h2 className="font-sans text-[15px] font-medium text-[--mia-text-primary] truncate">
41	          {conversationTitle || 'Nova Conversa'}
42	        </h2>
43	      </div>
44	
45	      <div className="flex items-center gap-1.5 shrink-0">
46	        <Popover open={popoverOpen} onOpenChange={setPopoverOpen}>
47	          <PopoverTrigger asChild>
48	            <Button
49	              variant="ghost"
50	              size="sm"
51	              className="h-9 gap-1.5 rounded-xl text-[--mia-text-secondary] hover:text-[--mia-accent] hover:bg-[--mia-accent-subtle] px-2 md:px-3 transition-colors"
52	              title="Histórico de conversas"
53	            >
54	              <History className="h-4 w-4" />
55	              <span className="hidden md:inline text-[13px] font-medium">
56	                Histórico
57	              </span>
58	            </Button>
59	          </PopoverTrigger>
60	          <PopoverContent
61	            className="w-80 p-0 border border-[--mia-glass-border] rounded-2xl overflow-hidden shadow-2xl bg-white dark:bg-[#1a1715]"
62	            align="end"
63	            sideOffset={8}
64	          >
65	            <MiaHistoryPopoverContent
66	              conversations={conversations}
67	              activeId={activeConversationId}
68	              onSelect={switchConversation}
69	              onDelete={deleteConversation}
70	              onClose={() => setPopoverOpen(false)}
71	            />
72	          </PopoverContent>
73	        </Popover>
74	        <Button data-mia-action="on-new-conversation"
75	          variant="ghost"
76	          size="sm"
77	          onClick={onNewConversation}
78	          className="h-9 gap-1.5 rounded-xl text-[--mia-text-secondary] hover:text-[--mia-accent] hover:bg-[--mia-accent-subtle] px-2 md:px-3 transition-colors"
79	          title="Nova conversa"
80	        >
81	          <SquarePen className="h-4 w-4" />
82	          <span className="hidden md:inline text-[13px] font-medium">
83	            Nova
84	          </span>
85	        </Button>
86	      </div>
87	    </header>
88	  );
89	}
