18	// ── Relative time ────────────────────────────────────────────
19	
20	function relativeTime(dateStr: string): string {
21	  const diff = Date.now() - new Date(dateStr).getTime();
22	  const mins = Math.floor(diff / 60000);
23	  if (mins < 1) return 'agora';
24	  if (mins < 60) return `${mins}min`;
25	  const hours = Math.floor(mins / 60);
26	  if (hours < 24) return `${hours}h`;
27	  const days = Math.floor(hours / 24);
28	  if (days < 7) return `${days}d`;
29	  return new Date(dateStr).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' });
30	}
31	
32	// ── Conversation list item ───────────────────────────────────
33	
