77	// ── Draggable floating panel ─────────────────────────────────
78	
79	function useDrag(initialPos: { x: number; y: number }) {
80	  const [pos, setPos] = useState(initialPos);
81	  const dragging = useRef(false);
82	  const offset = useRef({ x: 0, y: 0 });
83	
84	  const onMouseDown = useCallback((e: React.MouseEvent) => {
85	    dragging.current = true;
86	    offset.current = { x: e.clientX - pos.x, y: e.clientY - pos.y };
87	    e.preventDefault();
88	  }, [pos]);
89	
90	  useEffect(() => {
91	    const onMouseMove = (e: MouseEvent) => {
92	      if (!dragging.current) return;
93	      const newX = Math.max(0, Math.min(window.innerWidth - 100, e.clientX - offset.current.x));
94	      const newY = Math.max(0, Math.min(window.innerHeight - 100, e.clientY - offset.current.y));
95	      setPos({ x: newX, y: newY });
96	    };
97	    const onMouseUp = () => { dragging.current = false; };
98	    window.addEventListener('mousemove', onMouseMove);
99	    window.addEventListener('mouseup', onMouseUp);
100	    return () => {
101	      window.removeEventListener('mousemove', onMouseMove);
102	      window.removeEventListener('mouseup', onMouseUp);
103	    };
104	  }, []);
105	
106	  return { pos, onMouseDown, setPos };
107	}
108	
109	// ── Resize hook ──────────────────────────────────────────────
110	
111	type ResizeEdge = 'n' | 's' | 'e' | 'w' | 'ne' | 'nw' | 'se' | 'sw';
112	
113	function useResize(
114	  initialSize: { w: number; h: number },
115	  minSize = { w: 320, h: 250 },
116	  maxSize = { w: 800, h: typeof window !== 'undefined' ? window.innerHeight - 40 : 900 },
117	) {
118	  const [size, setSize] = useState(initialSize);
119	  const resizing = useRef<{ edge: ResizeEdge; startX: number; startY: number; startW: number; startH: number } | null>(null);
120	
121	  const onResizeStart = useCallback((edge: ResizeEdge, e: React.MouseEvent) => {
122	    resizing.current = { edge, startX: e.clientX, startY: e.clientY, startW: size.w, startH: size.h };
123	    e.preventDefault();
124	    e.stopPropagation();
125	  }, [size]);
126	
127	  useEffect(() => {
128	    const onMouseMove = (e: MouseEvent) => {
129	      const r = resizing.current;
130	      if (!r) return;
131	      const dx = e.clientX - r.startX;
132	      const dy = e.clientY - r.startY;
133	      let newW = r.startW;
134	      let newH = r.startH;
135	
136	      if (r.edge.includes('e')) newW = r.startW + dx;
137	      if (r.edge.includes('w')) newW = r.startW - dx;
138	      if (r.edge.includes('s')) newH = r.startH + dy;
139	      if (r.edge.includes('n')) newH = r.startH - dy;
140	
141	      setSize({
142	        w: Math.max(minSize.w, Math.min(maxSize.w, newW)),
143	        h: Math.max(minSize.h, Math.min(maxSize.h, newH)),
144	      });
145	    };
146	    const onMouseUp = () => { resizing.current = null; };
147	    window.addEventListener('mousemove', onMouseMove);
148	    window.addEventListener('mouseup', onMouseUp);
149	    return () => {
150	      window.removeEventListener('mousemove', onMouseMove);
151	      window.removeEventListener('mouseup', onMouseUp);
152	    };
153	  }, [minSize.w, minSize.h, maxSize.w, maxSize.h]);
154	
155	  return { size, setSize, onResizeStart, isResizing: () => resizing.current !== null };
156	}
157	
158	// ── Resize handle component ──────────────────────────────────
159	
160	function ResizeHandle({ edge, onResizeStart }: { edge: ResizeEdge; onResizeStart: (edge: ResizeEdge, e: React.MouseEvent) => void }) {
161	  const cursorMap: Record<ResizeEdge, string> = {
162	    n: 'cursor-n-resize', s: 'cursor-s-resize', e: 'cursor-e-resize', w: 'cursor-w-resize',
163	    ne: 'cursor-ne-resize', nw: 'cursor-nw-resize', se: 'cursor-se-resize', sw: 'cursor-sw-resize',
164	  };
165	  const posMap: Record<ResizeEdge, string> = {
166	    n: 'top-0 left-2 right-2 h-1.5',
167	    s: 'bottom-0 left-2 right-2 h-1.5',
168	    e: 'right-0 top-2 bottom-2 w-1.5',
169	    w: 'left-0 top-2 bottom-2 w-1.5',
170	    ne: 'top-0 right-0 h-3 w-3',
171	    nw: 'top-0 left-0 h-3 w-3',
172	    se: 'bottom-0 right-0 h-3 w-3',
173	    sw: 'bottom-0 left-0 h-3 w-3',
174	  };
175	
176	  return (
177	    <div
178	      className={cn('absolute z-10', cursorMap[edge], posMap[edge])}
179	      onMouseDown={(e) => onResizeStart(edge, e)}
180	    />
181	  );
182	}
183	
184	// ── Task Plan Card (preview → approve → progress) ────────────
185	
186	function TaskPlanCard({
187	  plan, onApprove, onCancel,
188	}: {
189	  plan: MiaTaskPlan; onApprove: () => void; onCancel: () => void;
190	}) {
191	  const completed = plan.items.filter(i => i.status === 'success').length;
192	  const failed = plan.items.filter(i => i.status === 'error').length;
193	  const total = plan.items.length;
194	  const isExecuting = plan.status === 'executing';
195	  const isDone = plan.status === 'completed';
196	  const progress = total > 0 ? Math.round((completed / total) * 100) : 0;
197	
198	  return (
199	    <div className="mx-2 mb-2 rounded-xl border border-emerald-500/30 bg-emerald-500/5 overflow-hidden">
200	      {/* Header */}
201	      <div className="px-3 py-2 border-b border-emerald-500/20 flex items-center justify-between">
202	        <div className="flex items-center gap-2">
203	          {isDone ? (
204	            <CheckCircle2 className="h-4 w-4 text-emerald-500" />
205	          ) : isExecuting ? (
206	            <Loader2 className="h-4 w-4 text-emerald-500 animate-spin" />
207	          ) : (
208	            <Play className="h-4 w-4 text-emerald-600" />
209	          )}
210	          <span className="text-xs font-semibold text-foreground">{plan.title}</span>
211	        </div>
212	        {(isExecuting || isDone) && (
213	          <span className="text-[11px] text-muted-foreground">{completed}/{total}{failed > 0 ? ` (${failed} erro${failed > 1 ? 's' : ''})` : ''}</span>
214	        )}
215	      </div>
216	
217	      {/* Progress bar */}
218	      {(isExecuting || isDone) && (
219	        <div className="h-1 bg-emerald-500/10">
220	          <div className="h-full bg-emerald-500 transition-all duration-300" style={{ width: `${progress}%` }} />
221	        </div>
222	      )}
223	
224	      {/* Items list */}
225	      <div className="max-h-[200px] overflow-y-auto divide-y divide-border/20">
226	        {plan.items.map((item, i) => (
227	          <div key={i} className={cn(
228	            "px-3 py-1.5 flex items-center gap-2 text-[12px]",
229	            item.status === 'running' && "bg-emerald-500/10",
230	            item.status === 'error' && "bg-red-500/5",
231	          )}>
232	            {item.status === 'success' ? <CheckCircle2 className="h-3 w-3 text-emerald-500 shrink-0" /> :
233	             item.status === 'error' ? <XCircle className="h-3 w-3 text-red-500 shrink-0" /> :
234	             item.status === 'running' ? <Loader2 className="h-3 w-3 text-emerald-500 animate-spin shrink-0" /> :
235	             <div className="h-3 w-3 rounded-full border border-border/50 shrink-0" />}
236	            <span className={cn("flex-1 truncate", item.status === 'error' && "text-red-600")}>{item.label}</span>
237	            {item.error_message && <span className="text-[10px] text-red-500 truncate max-w-[100px]">{item.error_message}</span>}
238	          </div>
239	        ))}
240	      </div>
241	
242	      {/* Actions */}
243	      {plan.status === 'preview' && (
244	        <div className="px-3 py-2 border-t border-emerald-500/20 flex items-center justify-between gap-2">
245	          <Button data-mia-action="on-cancel" variant="ghost" size="sm" className="h-7 text-xs" onClick={onCancel}>Cancelar</Button>
246	          <Button data-mia-action="on-approve" size="sm" className="h-7 text-xs bg-emerald-600 hover:bg-emerald-700" onClick={onApprove}>
247	            <Play className="h-3 w-3 mr-1" /> Aprovar e executar ({total} passo{total > 1 ? 's' : ''})
248	          </Button>
249	        </div>
250	      )}
251	      {isDone && (
252	        <div className="px-3 py-2 border-t border-emerald-500/20 text-center">
253	          <span className="text-[11px] text-emerald-600 font-medium">
254	            {failed === 0 ? `${total} passo${total > 1 ? 's' : ''} executado${total > 1 ? 's' : ''} com sucesso` : `${completed} ok, ${failed} com erro`}
255	          </span>
256	        </div>
257	      )}
258	    </div>
259	  );
260	}
261	
262	// ── Agent Bubble — Trae-style ReAct rounds with auto-fold, tool cards, state colors ──
263	
264	const TOOL_LABELS: Record<string, string> = {
265	  get_financial_summary: 'Resumo financeiro', compare_stores_financial: 'Comparando lojas',
266	  get_category_breakdown: 'Categorias DRE', get_overdue_analysis: 'Contas atrasadas',
267	  get_transactions: 'Buscando transações', get_invoices: 'Notas fiscais',
268	  get_cash_flow: 'Livro caixa', query_database: 'Consultando banco',
269	  think: 'Raciocinando', save_knowledge: 'Salvando insight',
270	  execute_operation: 'Operação em lote', batch_undo: 'Desfazendo', session_rollback: 'Revertendo sessão',
271	};
272	
273	const STATE_CFG: Record<string, { color: string; spinning: boolean; label: string }> = {
274	  thinking:      { color: 'text-blue-500',    spinning: true,  label: 'Pensando' },
275	  calling_tools: { color: 'text-amber-500',   spinning: true,  label: 'Consultando' },
276	  tools_done:    { color: 'text-emerald-500',  spinning: false, label: 'Dados obtidos' },
277	  reflecting:    { color: 'text-purple-500',   spinning: true,  label: 'Corrigindo' },
278	  completed:     { color: 'text-emerald-500',  spinning: false, label: 'Concluído' },
279	  error:         { color: 'text-red-500',      spinning: false, label: 'Erro' },
280	};
281	
282	function AgentBubble({ status, steps, streamingText, agentRounds = [], thinkingBlocks = [] }: {
283	  status: string | null; steps: MiaExecutionStep[]; streamingText: string;
284	  agentRounds?: import('@/types/mia').MiaAgentRound[];
285	  thinkingBlocks?: { round: number; content: string; durationMs: number }[];
286	}) {
287	  const hasRounds = agentRounds.length > 0;
288	  const hasSteps = steps.length > 0;
289	  const hasText = streamingText.length > 0;
290	  const latestRound = agentRounds[agentRounds.length - 1];
291	
292	  return (
293	    <div className="flex gap-2.5 animate-in fade-in slide-in-from-bottom-2 duration-300">
294	      <div className="h-7 w-7 rounded-full bg-gradient-to-br from-emerald-500 to-teal-600 flex items-center justify-center shrink-0 mt-0.5 shadow-sm">
295	        <Sparkles className={cn("h-3.5 w-3.5 text-white", !hasText && "animate-pulse")} />
296	      </div>
297	      <div className="flex-1 min-w-0 max-w-[88%] rounded-2xl rounded-bl-md bg-card border border-border/40 shadow-sm overflow-hidden">
298	
299	        {/* ── ReAct Rounds with Reasoning + Tool Cards ── */}
300	        {hasRounds && (<div className="divide-y divide-border/10">
301	          {agentRounds.map((round) => {
302	            const cfg = STATE_CFG[round.state] || STATE_CFG.thinking;
303	            const isLatest = round === latestRound;
304	            const isDone = round.state === 'completed' || round.state === 'tools_done';
305	            const thinking = thinkingBlocks.find(t => t.round === round.round);
306	
307	            return (<div key={round.round} className={cn("transition-all duration-300", isLatest && !isDone && "bg-muted/10")}>
308	
309	              {/* ── Reasoning block (Cursor/Claude Code style) ── */}
310	              {thinking && (
311	                <Collapsible defaultOpen={false}>
312	                  <CollapsibleTrigger className="w-full flex items-center gap-1.5 px-3 py-1 text-[10px] text-muted-foreground/40 hover:text-muted-foreground/60 transition-colors group">
313	                    <Brain className="h-2.5 w-2.5 shrink-0" />
314	                    <span className="italic">pensou por {(thinking.durationMs / 1000).toFixed(1)}s</span>
315	                    <ChevronRight className="h-2.5 w-2.5 shrink-0 transition-transform group-data-[state=open]:rotate-90" />
316	                  </CollapsibleTrigger>
317	                  <CollapsibleContent>
